import java.util.*;
import java.io.*;

public class Main {
    static class Modular {
        private int val;
        public static final int MOD = 1000000007;

        public Modular() {
            this.val = 0;
        }

        public Modular(long v) {
            this.val = (int)(v % MOD);
            if (this.val < 0) this.val += MOD;
        }

        public static int computeInverse(int a, int m) {
            if (m == 1) return 0;
            a %= m;
            if (a < 0) a += m;
            if (a == 0) throw new ArithmeticException("Inverse does not exist");
            if (a == 1) return 1;
            return m - computeInverse(m, a) * m / a;
        }

        public Modular invert() {
            int inv = computeInverse(this.val, MOD);
            return new Modular(inv);
        }

        public Modular add(Modular o) {
            int res = this.val + o.val;
            if (res >= MOD) res -= MOD;
            return new Modular(res);
        }

        public Modular subtract(Modular o) {
            int res = this.val - o.val;
            if (res < 0) res += MOD;
            return new Modular(res);
        }

        public Modular multiply(Modular o) {
            long res = (long) this.val * o.val % MOD;
            return new Modular(res);
        }

        public Modular divide(Modular o) {
            return this.multiply(o.invert());
        }

        public int toInt() {
            return this.val;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        final int n = 6;
        Modular[][] p = new Modular[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                p[i][j] = new Modular(0);
            }
        }

        int _n = Integer.parseInt(br.readLine());
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < _n; j++) {
                int a = Integer.parseInt(br.readLine());
                p[i][j] = new Modular(a).divide(new Modular(100));
            }
        }

        final int f = 20;
        Modular[][] sets = new Modular[2][1 << f];
        for (int t = 0; t < 2; t++) {
            for (int j = 0; j < (1 << f); j++) {
                sets[t][j] = new Modular(0);
            }
        }

        List<Integer>[] masks = new List[2];
        masks[0] = new ArrayList<>();
        masks[1] = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                for (int k = 0; k < j; k++) {
                    int maskVal = (1 << i) ^ (1 << j) ^ (1 << k);
                    masks[0].add(maskVal);
                    masks[1].add(((1 << n) - 1) ^ maskVal);
                }
            }
        }

        if (f != masks[0].size()) {
            throw new RuntimeException("Mismatch in mask size");
        }

        for (int t = 0; t < 2; t++) {
            int limit = 1 << (n / 2 * n);
            for (int e = 0; e < limit; e++) {
                Modular prob = new Modular(1);
                int[] edges = new int[n / 2];
                Arrays.fill(edges, 0);
                for (int i = 0; i < n / 2 * n; i++) {
                    boolean r = ((e >> i) & 1) == 1;
                    Modular pp = p[(i / n) * 2 + t][i % n];
                    prob = r ? prob.multiply(pp) : prob.multiply(new Modular(1).subtract(pp));
                    edges[i / n] |= (r ? 1 : 0) << (i % n);
                }
                int work_mask = 0;
                for (int a = 0; a < masks[t].size(); a++) {
                    int mask = masks[t].get(a);
                    int[] r = new int[n / 2];
                    for (int i = 0; i < n / 2; i++) {
                        r[i] = edges[i] & mask;
                    }
                    if (r[0] != 0 && r[1] != 0 && r[2] != 0) {
                        int total = r[0] | r[1] | r[2];
                        if (Integer.bitCount(total) == 3) {
                            int x = Integer.bitCount(r[0] | r[1]);
                            int y = Integer.bitCount(r[0] | r[2]);
                            int z = Integer.bitCount(r[1] | r[2]);
                            if (x >= 2 && y >= 2 && z >= 2) {
                                work_mask |= (1 << a);
                            }
                        }
                    }
                }
                sets[t][work_mask] = sets[t][work_mask].add(prob);
            }
        }

        for (int i = 0; i < f; i++) {
            for (int j = 0; j < (1 << f); j++) {
                if (((j >> i) & 1) == 1) continue;
                sets[0][j ^ (1 << i)] = sets[0][j ^ (1 << i)].add(sets[0][j]);
            }
        }

        Modular answer_final = new Modular(0);
        int fullMask = (1 << f) - 1;
        for (int j = 0; j < (1 << f); j++) {
            Modular term = sets[0][j].multiply(sets[1][fullMask ^ j]);
            answer_final = answer_final.add(term);
        }
        answer_final = new Modular(1).subtract(answer_final);
        System.out.println(answer_final.toInt());
    }
}
